const bookings = $input.all();

let highest = 0;

for (const item of bookings) {
  const id = item.json?.Booking_ID;

  if (!id) continue;

  const match = id.match(/^RB-(\d+)$/);

  if (match) {
    const number = parseInt(match[1], 10);

    if (number > highest) {
      highest = number;
    }
  }
}

const nextNumber = highest + 1;

const bookingId = `RB-${String(nextNumber).padStart(6, '0')}`;

return bookingId;

